    public static string GetPath(string iconKey)
    {
        if (string.IsNullOrWhiteSpace(iconKey)) return DefaultSearchIcon;
        if (EngineIcons.TryGetValue(iconKey, out var path)) return path;
        return DefaultSearchIcon;
    }
